CREATE TABLE IF NOT EXISTS src_crm.crm_lead(id BIGINT AUTO_INCREMENT PRIMARY KEY,lead_no VARCHAR(32) NOT NULL UNIQUE,customer_name VARCHAR(200) NOT NULL,contact_name VARCHAR(50),contact_phone VARCHAR(30),source_channel VARCHAR(32),intent_level VARCHAR(16) DEFAULT 'MEDIUM',score INT DEFAULT 0,expected_close_date DATE,owner_user VARCHAR(32),status VARCHAR(20) NOT NULL DEFAULT 'NEW',converted_opportunity_no VARCHAR(32),invalid_reason VARCHAR(300),created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY idx_lead_status(status),KEY idx_lead_owner(owner_user));
CREATE TABLE IF NOT EXISTS src_crm.crm_lead_follow(id BIGINT AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT NOT NULL,follow_type VARCHAR(16) NOT NULL,content VARCHAR(1000) NOT NULL,next_follow_at DATETIME(3),follow_user VARCHAR(32),follow_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),KEY idx_lead_follow(lead_id,follow_at));
CREATE TABLE IF NOT EXISTS src_crm.crm_lead_assignment(id BIGINT AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT NOT NULL,from_user VARCHAR(32),to_user VARCHAR(32) NOT NULL,reason VARCHAR(300),assigned_by VARCHAR(32),assigned_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),KEY idx_assignment_lead(lead_id));
CREATE TABLE IF NOT EXISTS src_crm.crm_complaint(id BIGINT AUTO_INCREMENT PRIMARY KEY,complaint_no VARCHAR(32) NOT NULL UNIQUE,customer_code VARCHAR(32) NOT NULL,sales_order_no VARCHAR(32),delivery_no VARCHAR(32),product_code VARCHAR(32),batch_no VARCHAR(64),severity VARCHAR(16) NOT NULL,problem_desc VARCHAR(1000) NOT NULL,responsible_dept VARCHAR(64),solution VARCHAR(1000),customer_feedback VARCHAR(1000),status VARCHAR(16) DEFAULT 'OPEN',created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),closed_at DATETIME(3),KEY idx_complaint_customer(customer_code),KEY idx_complaint_status(status));
